DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['dealership','profile','device','setting','setting_history','supplier','yard_zone','yard_slot','vehicle','vehicle_event','vehicle_work','vehicle_condition','vehicle_damage','vehicle_photo','listing','customer','lead','lead_event','conversation','appointment','deal','deal_item','contract','import_job','import_row','outbox','notification','message_template'] LOOP EXECUTE format('ALTER TABLE etidealcrm.%I ENABLE ROW LEVEL SECURITY', t); END LOOP; END $$;

CREATE POLICY dealership_select ON etidealcrm.dealership FOR SELECT TO authenticated USING ((SELECT etidealcrm.is_active_user()) AND id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY dealership_update ON etidealcrm.dealership FOR UPDATE TO authenticated USING ((SELECT etidealcrm.can_manage_users()) AND id = (SELECT etidealcrm.current_dealership_id())) WITH CHECK (id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY profile_select ON etidealcrm.profile FOR SELECT TO authenticated USING ((SELECT etidealcrm.is_active_user()) AND dealership_id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY profile_insert ON etidealcrm.profile FOR INSERT TO authenticated WITH CHECK ((SELECT etidealcrm.can_manage_users()));
CREATE POLICY profile_update ON etidealcrm.profile FOR UPDATE TO authenticated USING ((SELECT etidealcrm.is_active_user()) AND ((SELECT etidealcrm.can_manage_users()) OR id = (SELECT auth.uid()))) WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY device_select ON etidealcrm.device FOR SELECT TO authenticated USING ((SELECT etidealcrm.is_active_user()) AND ((SELECT etidealcrm.can_manage_users()) OR user_id = (SELECT auth.uid())));
CREATE POLICY device_insert ON etidealcrm.device FOR INSERT TO authenticated WITH CHECK ((SELECT etidealcrm.is_active_user()) AND user_id = (SELECT auth.uid()) AND status = 'pending');
CREATE POLICY device_update ON etidealcrm.device FOR UPDATE TO authenticated USING ((SELECT etidealcrm.can_manage_users()) OR user_id = (SELECT auth.uid())) WITH CHECK (true);
CREATE POLICY setting_select ON etidealcrm.setting FOR SELECT TO authenticated USING ((SELECT etidealcrm.is_active_user()) AND dealership_id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY setting_write ON etidealcrm.setting FOR ALL TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_setting_key(key))) WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_setting_key(key)));
CREATE POLICY setting_history_select ON etidealcrm.setting_history FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM etidealcrm.setting s WHERE s.id = setting_id AND s.dealership_id = (SELECT etidealcrm.current_dealership_id())) AND (SELECT etidealcrm.is_active_user()));
CREATE POLICY supplier_select ON etidealcrm.supplier FOR SELECT TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_read_suppliers()));
CREATE POLICY supplier_write ON etidealcrm.supplier FOR ALL TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_suppliers())) WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_suppliers()));
CREATE POLICY yard_zone_select ON etidealcrm.yard_zone FOR SELECT TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_read_yard()));
CREATE POLICY yard_zone_write ON etidealcrm.yard_zone FOR ALL TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_yard())) WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_yard()));
CREATE POLICY yard_slot_select ON etidealcrm.yard_slot FOR SELECT TO authenticated USING ((SELECT etidealcrm.can_read_yard()) AND EXISTS (SELECT 1 FROM etidealcrm.yard_zone z WHERE z.id = zone_id AND z.dealership_id = (SELECT etidealcrm.current_dealership_id())));
CREATE POLICY yard_slot_write ON etidealcrm.yard_slot FOR ALL TO authenticated USING ((SELECT etidealcrm.can_write_yard()) AND EXISTS (SELECT 1 FROM etidealcrm.yard_zone z WHERE z.id = zone_id AND z.dealership_id = (SELECT etidealcrm.current_dealership_id()))) WITH CHECK ((SELECT etidealcrm.can_write_yard()));
